// Tests for JpegDecoderGpu (Images/Jpeg).
//
// Fixtures (TestData/Jpeg, generated by scripts/images/make_jpeg_fixtures.py): grayscale, 4:4:4 / 4:2:2 / 4:2:0 /
// 4:4:0 / 4:1:1 and odd layouts, odd and non-MCU-aligned sizes (1x1, 7x5, 17x33, 100x75), quality 1..100,
// progressive (spectral selection + successive approximation), optimized tables, restart intervals (baseline and
// progressive), EXIF orientation 1..8, Adobe CMYK / YCCK / RGB, extended sequential, a larger photographic picture.
// The expected pixels (.rgba8) are Pillow's own decode (libjpeg-turbo: ISLOW IDCT, fancy upsampling, fixed-point
// colour conversion) converted to RGBA8, so the GPU decoder must match the reference decoder BIT-EXACT; nothing is
// derived from our own code. The orientation truth (.oriented.rgba8) is Pillow's ImageOps.exif_transpose.
//
// What can fail: the managed overload and the ArrayView1D overload (into a caller buffer pre-filled with 0xAB, so a
// decoder that wrote elsewhere / short leaves 0xAB), RGBA8 and RGBA16 output, ApplyOrientation, and the error paths
// (bad signature, truncation at several places, unsupported features, corrupt entropy data) which must throw
// ImageDecodeException with the specific reason.

using ILGPU;
using ILGPU.Runtime;
using SpawnDev.Codecs.Images;
using SpawnDev.Codecs.Images.Jpeg;
using SpawnDev.ILGPU;
using SpawnDev.SpawnJS.JSObjects;
using SpawnDev.UnitTesting;
using static SpawnDev.Codecs.Demo.Shared.UnitTests.TestHelpers;

namespace SpawnDev.Codecs.Demo.Shared.UnitTests;

public abstract partial class CodecsTestBase
{
    private const string JpegFixturePrefix = "SpawnDev.Codecs.Demo.Shared.TestData.Jpeg.";

    /// <summary>Names of the JPEG fixtures that have a Pillow truth file (everything but the broken-file set).</summary>
    private static string[] JpegTruthFixtureNames()
    {
        var names = typeof(CodecsTestBase).Assembly.GetManifestResourceNames()
            .Where(n => n.StartsWith(JpegFixturePrefix, StringComparison.Ordinal) && n.EndsWith(".jpg", StringComparison.Ordinal))
            .Select(n => n.Substring(JpegFixturePrefix.Length, n.Length - JpegFixturePrefix.Length - 4))
            .Where(n => HasEmbedded(JpegFixturePrefix + n + ".rgba8"))
            .OrderBy(n => n, StringComparer.Ordinal)
            .ToArray();
        if (names.Length == 0) throw new InvalidOperationException("No JPEG fixtures are embedded.");
        return names;
    }

    [TestMethod(Timeout = 600000)]
    public async Task JpegDecoderGpu_AllFixtures_Rgba8_MatchPillow_ManagedAndArrayView()
    {
        var (ctx, acc) = await AcquireAcceleratorOrSkipAsync();
        RequireFeatures(acc, SerialStreamKernels);
        try
        {
            using var dec = new JpegDecoderGpu(acc);
            var failures = new List<string>();
            int checkedCount = 0;
            foreach (var name in JpegTruthFixtureNames())
            {
                byte[] jpg = ReadEmbedded(JpegFixturePrefix + name + ".jpg");
                byte[] expected = ReadEmbedded(JpegFixturePrefix + name + ".rgba8");
                try
                {
                    // Managed overload.
                    var managed = await dec.DecodeAsync(jpg);
                    var diff = ComparePixels(expected, managed.Pixels, 4, managed.Info.Width);
                    if (diff != null) failures.Add($"{name} [managed]: {diff}");

                    // ArrayView1D overload into a poisoned caller buffer, longer than needed.
                    using var dFile = acc.Allocate1D<byte>(jpg.Length + 11);
                    DeviceTransfer.Upload(dFile.View, jpg);
                    using var dOut = acc.Allocate1D<byte>(expected.Length + 7);
                    var fill = new byte[dOut.Length];
                    System.Array.Fill(fill, (byte)0xAB);
                    DeviceTransfer.Upload(dOut.View, fill);
                    var info = await dec.DecodeAsync(dFile.View, jpg.Length, dOut.View, PixelFormat.Rgba8);
                    var viewPixels = await DeviceTransfer.DownloadAsync(dOut.View, expected.Length);
                    diff = ComparePixels(expected, viewPixels, 4, info.Width);
                    if (diff != null) failures.Add($"{name} [ArrayView1D]: {diff}");
                    var tail = await DeviceTransfer.DownloadAsync(dOut.View, dOut.Length);
                    for (int i = expected.Length; i < tail.Length; i++)
                        if (tail[i] != 0xAB) { failures.Add($"{name} [ArrayView1D]: wrote past the end of the image at byte {i}"); break; }
                    checkedCount++;
                }
                catch (Exception ex)
                {
                    failures.Add($"{name}: {ex.GetType().Name}: {ex.Message}");
                }
            }
            True(checkedCount > 50, $"only {checkedCount} fixtures were exercised");
            True(failures.Count == 0,
                $"{failures.Count} of {checkedCount + failures.Count} JPEG fixtures failed:\n" + string.Join("\n", failures));
        }
        finally { ReleaseAccelerator(ctx, acc); }
    }

    [TestMethod]
    public async Task JpegDecoderGpu_Rgba16_IsRgba8Replicated()
    {
        var (ctx, acc) = await AcquireAcceleratorOrSkipAsync();
        RequireFeatures(acc, SerialStreamKernels);
        try
        {
            using var dec = new JpegDecoderGpu(acc);
            var failures = new List<string>();
            foreach (var name in new[] { "c420_100x75", "prog_c444_17x33", "gray_7x5", "cmyk_adobe_33x17" })
            {
                byte[] jpg = ReadEmbedded(JpegFixturePrefix + name + ".jpg");
                byte[] e8 = ReadEmbedded(JpegFixturePrefix + name + ".rgba8");
                var img = await dec.DecodeAsync(jpg, PixelFormat.Rgba16);
                if (img.Pixels.Length != e8.Length * 2) { failures.Add($"{name}: length {img.Pixels.Length}"); continue; }
                var expected = new byte[e8.Length * 2];
                for (int i = 0; i < e8.Length; i++) { expected[2 * i] = e8[i]; expected[2 * i + 1] = e8[i]; }   // v * 257, little endian
                var diff = ComparePixels(expected, img.Pixels, 8, img.Info.Width);
                if (diff != null) failures.Add($"{name}: {diff}");
            }
            True(failures.Count == 0, string.Join("\n", failures));
        }
        finally { ReleaseAccelerator(ctx, acc); }
    }

    [TestMethod]
    public async Task JpegDecoderGpu_ReadInfo_ReportsHeaderFacts()
    {
        var (ctx, acc) = await AcquireAcceleratorOrSkipAsync();
        RequireFeatures(acc, SerialStreamKernels);
        try
        {
            using var dec = new JpegDecoderGpu(acc);
            var info = await dec.ReadInfoAsync(ReadEmbedded(JpegFixturePrefix + "prog_c420_66x50.jpg"));
            Equal(ImageFormat.Jpeg, info.Format, "format");
            Equal(66, info.Width, "width");
            Equal(50, info.Height, "height");
            Equal(8, info.BitDepth, "bit depth");
            True(info.IsInterlaced, "progressive reports IsInterlaced");
            True(!info.HasAlpha, "JPEG has no alpha");
            Equal(1, info.FrameCount, "frames");
            Equal(1, info.Orientation, "no EXIF -> orientation 1");

            var baseline = await dec.ReadInfoAsync(ReadEmbedded(JpegFixturePrefix + "c420_17x33.jpg"));
            True(!baseline.IsInterlaced, "baseline is not progressive");
            Equal(17, baseline.Width, "baseline width");
            Equal(33, baseline.Height, "baseline height");

            for (int o = 1; o <= 8; o++)
            {
                var oi = await dec.ReadInfoAsync(ReadEmbedded(JpegFixturePrefix + $"orient_{o}.jpg"));
                Equal(o, oi.Orientation, $"orient_{o} EXIF orientation");
                Equal(24, oi.Width, $"orient_{o} width (orientation is reported, not applied)");
                Equal(16, oi.Height, $"orient_{o} height");
            }

            // The ArrayView1D overload of ReadInfo (file already on the accelerator).
            var jpg = ReadEmbedded(JpegFixturePrefix + "c444_7x5.jpg");
            using var dFile = acc.Allocate1D<byte>(jpg.Length + 5);
            DeviceTransfer.Upload(dFile.View, jpg);
            var vi = await dec.ReadInfoAsync(dFile.View, jpg.Length);
            Equal(7, vi.Width, "view width");
            Equal(5, vi.Height, "view height");
        }
        finally { ReleaseAccelerator(ctx, acc); }
    }

    [TestMethod]
    public async Task JpegDecoderGpu_ApplyOrientation_MatchesPillowTranspose()
    {
        var (ctx, acc) = await AcquireAcceleratorOrSkipAsync();
        RequireFeatures(acc, SerialStreamKernels);
        try
        {
            using var dec = new JpegDecoderGpu(acc);
            var failures = new List<string>();
            var options = new JpegDecodeOptions { ApplyOrientation = true };
            for (int o = 1; o <= 8; o++)
            {
                byte[] jpg = ReadEmbedded(JpegFixturePrefix + $"orient_{o}.jpg");
                byte[] truth = ReadEmbedded(JpegFixturePrefix + $"orient_{o}.oriented.rgba8");
                int tw = BitConverter.ToInt32(truth, 0), th = BitConverter.ToInt32(truth, 4);
                var expected = truth.AsSpan(8).ToArray();
                try
                {
                    var img = await dec.DecodeAsync(jpg, PixelFormat.Rgba8, options);
                    if (img.Info.Width != tw || img.Info.Height != th)
                        failures.Add($"orient_{o}: size {img.Info.Width}x{img.Info.Height}, expected {tw}x{th}");
                    if (img.Info.Orientation != 1) failures.Add($"orient_{o}: info.Orientation {img.Info.Orientation} after applying");
                    var diff = ComparePixels(expected, img.Pixels, 4, tw);
                    if (diff != null) failures.Add($"orient_{o} [managed]: {diff}");

                    // Default options must leave the pixels as stored.
                    var plain = await dec.DecodeAsync(jpg);
                    if (plain.Info.Orientation != o) failures.Add($"orient_{o}: default decode reports {plain.Info.Orientation}");
                }
                catch (Exception ex)
                {
                    failures.Add($"orient_{o}: {ex.GetType().Name}: {ex.Message}");
                }
            }
            True(failures.Count == 0, string.Join("\n", failures));
        }
        finally { ReleaseAccelerator(ctx, acc); }
    }

    [TestMethod]
    public async Task JpegDecoderGpu_BaselineWithoutEoi_DecodesWhenAllDataIsPresent()
    {
        var (ctx, acc) = await AcquireAcceleratorOrSkipAsync();
        RequireFeatures(acc, SerialStreamKernels);
        try
        {
            using var dec = new JpegDecoderGpu(acc);
            var jpg = ReadEmbedded(JpegFixturePrefix + "c420_100x75.jpg");
            True(jpg[^2] == 0xFF && jpg[^1] == 0xD9, "fixture ends with EOI");
            var expected = ReadEmbedded(JpegFixturePrefix + "c420_100x75.rgba8");
            var img = await dec.DecodeAsync(jpg.AsMemory(0, jpg.Length - 2));
            var diff = ComparePixels(expected, img.Pixels, 4, img.Info.Width);
            True(diff == null, $"baseline file without EOI: {diff}");
        }
        finally { ReleaseAccelerator(ctx, acc); }
    }

    private static string Sha256Hex(byte[] data) =>
        Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(data)).ToLowerInvariant();

    private static string ReadEmbeddedText(string resourceName) =>
        System.Text.Encoding.ASCII.GetString(ReadEmbedded(resourceName)).Trim();

    [TestMethod(Timeout = 600000)]
    public async Task JpegDecoderGpu_ProductionScale_1024x768_MatchesPillowSha256()
    {
        var (ctx, acc) = await AcquireAcceleratorOrSkipAsync();
        RequireFeatures(acc, SerialStreamKernels);
        try
        {
            using var dec = new JpegDecoderGpu(acc);
            var failures = new List<string>();
            // baseline 4:2:0, progressive 4:4:4 with optimized tables, baseline 4:2:2 with a restart marker every MCU row
            foreach (var name in new[] { "big_c420_1024x768", "big_prog_c444_1024x768", "big_rst_c422_1024x768" })
            {
                var img = await dec.DecodeAsync(ReadEmbedded(JpegFixturePrefix + name + ".jpg"));
                if (img.Info.Width != 1024 || img.Info.Height != 768) { failures.Add($"{name}: size {img.Info.Width}x{img.Info.Height}"); continue; }
                string got = Sha256Hex(img.Pixels);
                string want = ReadEmbeddedText(JpegFixturePrefix + name + ".sha256");
                if (got != want) failures.Add($"{name}: RGBA sha256 {got} != Pillow's {want}");
            }
            True(failures.Count == 0, string.Join("\n", failures));
        }
        finally { ReleaseAccelerator(ctx, acc); }
    }

