    [TestMethod]
    public async Task JpegDecoderGpu_TypedArrayOverload_MatchesPillow()
    {
        if (!OperatingSystem.IsBrowser())
            throw new UnsupportedTestException("TypedArray overloads need a browser accelerator.");
        var (ctx, acc) = await AcquireAcceleratorOrSkipAsync();
        RequireFeatures(acc, SerialStreamKernels);
        try
        {
            using var dec = new JpegDecoderGpu(acc);
            await RunJpegTypedArrayDecode(dec);
        }
        finally { ReleaseAccelerator(ctx, acc); }
    }

    [System.Runtime.Versioning.SupportedOSPlatform("browser")]
    private static async Task RunJpegTypedArrayDecode(JpegDecoderGpu dec)
    {
        foreach (var name in new[] { "c420_100x75", "prog_c444_66x50", "rst_b3_gray" })
        {
            byte[] jpg = ReadEmbedded(JpegFixturePrefix + name + ".jpg");
            byte[] expected = ReadEmbedded(JpegFixturePrefix + name + ".rgba8");
            using var jsFile = new Uint8Array(jpg.Length); jsFile.Set(jpg);
            var info = await dec.ReadInfoAsync(jsFile);
            using var img = await dec.DecodeAsync(jsFile);
            Equal(info.Width, img.Info.Width, $"{name} width");
            // Reading back to .NET is the TEST's terminal compare, not the product path.
            var diff = ComparePixels(expected, img.Pixels.ReadBytes(), 4, img.Info.Width);
            True(diff == null, $"{name} [TypedArray]: {diff}");
        }
    }

    private async Task AssertJpegRejectedAsync(string fixture, string expectedMessagePart)
    {
        var (ctx, acc) = await AcquireAcceleratorOrSkipAsync();
        RequireFeatures(acc, SerialStreamKernels);
        try
        {
            using var dec = new JpegDecoderGpu(acc);
            ImageDecodeException? caught = null;
            try { await dec.DecodeAsync(ReadEmbedded(JpegFixturePrefix + fixture + ".jpg")); }
            catch (ImageDecodeException ex) { caught = ex; }
            NotNull(caught, $"{fixture}: expected ImageDecodeException");
            Contains(expectedMessagePart, caught!.Message, fixture);
        }
        finally { ReleaseAccelerator(ctx, acc); }
    }

    [TestMethod]
    public async Task JpegDecoderGpu_BrokenFiles_ReportSpecificReasons()
    {
        var expectations = new (string Fixture, string Reason)[]
        {
            ("bad_soi", "missing SOI"),
            ("bad_cut_in_dqt", "truncated"),
            ("bad_cut_in_scan", "entropy-coded data is truncated"),
            ("bad_cut_in_scan_prog", "entropy-coded data is truncated"),
            ("bad_prog_no_eoi", "without an EOI"),
            ("bad_no_sof", "no frame header"),
            ("bad_no_dht", "Huffman table slot"),
            ("bad_no_dqt", "quantization table"),
            ("bad_12bit", "12-bit JPEG is not supported"),
            ("bad_12bit_sof1", "12-bit JPEG is not supported"),
            ("bad_arithmetic", "arithmetic"),
            ("bad_lossless", "lossless"),
            ("bad_zero_width", "width is zero"),
            ("bad_zero_height", "height is zero"),
            ("bad_sampling_factor", "sampling factors"),
            ("bad_restart_missing", "restart markers"),
            ("bad_restart_order", "restart markers"),
            ("bad_huffman_code", "not a Huffman code"),
            ("bad_run_overflow", "coefficient run"),
            ("bad_fractional_sampling", "fractional ratio"),
            ("bad_huffman_oversubscribed", "Huffman table"),
            ("bad_sos_unknown_component", "component selector not in the frame"),
            ("bad_dqt_short", "quantization table segment"),
            ("bad_marker_junk", "does not start with 0xFF"),
            ("bad_sof_twice", "more than one frame header"),
            ("bad_progressive_params", "spectral selection"),
            ("bad_no_scan", "no scan"),
            ("bad_only_soi_eoi", "no frame header"),
            ("bad_too_short", "truncated"),
            ("bad_huffman_dc_symbol", "Huffman table"),
            ("bad_missing_component_scan", "not completely covered"),
            ("bad_too_many_scans", "more than 128 scans"),
            ("bad_too_large", "too large"),
            ("bad_sos_duplicate_component", "listed twice"),
            ("bad_sos_table_selector", "Huffman table selector"),
            ("bad_mcu_too_many_blocks", "more than 10 blocks"),
        };
        var (ctx, acc) = await AcquireAcceleratorOrSkipAsync();
        RequireFeatures(acc, SerialStreamKernels);
        try
        {
            var dec = new JpegDecoderGpu(acc);
            var failures = new List<string>();
            foreach (var (fixture, reason) in expectations)
            {
                try
                {
                    await dec.DecodeAsync(ReadEmbedded(JpegFixturePrefix + fixture + ".jpg"));
                    failures.Add($"{fixture}: decoded without error (expected \"{reason}\")");
                }
                catch (ImageDecodeException ex)
                {
                    if (!ex.Message.Contains(reason, StringComparison.Ordinal))
                        failures.Add($"{fixture}: message \"{ex.Message}\" does not contain \"{reason}\"");
                }
                catch (Exception ex)
                {
                    failures.Add($"{fixture}: {ex.GetType().Name}: {ex.Message}");
                }

                // The decoder must stay usable after an error: a good file decodes next. A device fault (e.g. a CUDA illegal
                // memory access from an out-of-bounds read on the broken file) surfaces here at the latest; name the fixture
                // and stop, since the context is poisoned and every later check would report the same fault.
                try
                {
                    var good = await dec.DecodeAsync(ReadEmbedded(JpegFixturePrefix + "gray_7x5.jpg"));
                    var diff = ComparePixels(ReadEmbedded(JpegFixturePrefix + "gray_7x5.rgba8"), good.Pixels, 4, 7);
                    if (diff != null) failures.Add($"{fixture}: decoder unusable after the error: {diff}");
                }
                catch (Exception ex)
                {
                    failures.Add($"{fixture}: the good file after it failed (device fault from this broken file?): {ex.GetType().Name}: {ex.Message}");
                    break;
                }
            }
            // A poisoned device context also throws from Dispose; report the checks, not the teardown. After a failure the
            // shared accelerator is dropped so the next test does not inherit a faulted device.
            string? teardown = null;
            try { dec.Dispose(); }
            catch (Exception ex) { teardown = $"(teardown also failed: {ex.GetType().Name}: {ex.Message.Split('\n')[0]})"; }
            if (failures.Count > 0 || teardown != null) DiscardAccelerator();
            else ReleaseAccelerator(ctx, acc);
            True(failures.Count == 0, $"{failures.Count} broken-file checks failed:\n" + string.Join("\n", failures) + (teardown ?? ""));
        }
        catch
        {
            DiscardAccelerator();
            throw;
        }
    }
}
